def f(x):
    return 2**(-1.0/((x-1)**2))

def delta(eps):
    # proposed rule
    if eps >= 1:
        return 1.0
    return math.sqrt(math.log(2)/math.log(1.0/eps))

print("eps      delta        f(1+delta) (boundary)   max over punctured nbhd   all<eps?")
for eps in [0.9, 0.5, 0.1, 0.01, 0.001, 1e-8, 1.0, 2.0, 10.0]:
    d = delta(eps)
    # sample many points with 0 < |x-1| < d, both sides
    ts = [k/1000 for k in range(1, 1000)]
    vals = [f(1 + d*t) for t in ts] + [f(1 - d*t) for t in ts]
    mx = max(vals)
    b = f(1+d)
    print(f"{eps:<8g} {d:<12.6f} {b:<25.8g} {mx:<23.8g} {mx < eps}")

# check the closed-form single formula: delta = sqrt(ln2 / max(ln(1/eps), ln2))
def delta_one(eps):
    return math.sqrt(math.log(2)/max(math.log(1.0/eps), math.log(2)))

print("\nsingle-formula check (must equal the case-split rule, and always be a valid delta):")
for eps in [0.9, 0.5, 0.1, 0.01, 1e-8, 1.0, 2.0]:
    d1, d2 = delta(eps), delta_one(eps)
    ts = [k/2000 for k in range(1, 2000)]
    mx = max([f(1+d1*t) for t in ts] + [f(1-d1*t) for t in ts])
    print(f"eps={eps:<8g} piecewise={d1:<10.6f} single={d2:<10.6f} max_f={mx:<14.8g} ok={mx<eps}")

# sanity: as eps -> 0, delta -> 0 (required: delta must be positive and shrink)
for eps in [1e-3, 1e-6, 1e-12, 1e-40]:
    print("eps=", eps, "delta=", delta(eps))
"}

