from fractions import Fraction as F

# elements of Q(s), s = i*sqrt(7), s^2 = -7 : pairs (a,b) = a + b*s
def mul(u,v):
    a,b=u; c,d=v
    return (a-7*b*d, b*c+a*d)
def add(u,v): return (u[0]+v[0], u[1]+v[1])
def sub(u,v): return (u[0]-v[0], u[1]-v[1])
def sc(n,u): return (F(n)*u[0], F(n)*u[1])
def show(u): return "%s + (%s)*s"%(u[0],u[1])

ONE=(F(1),F(0))
# cubic 1: x^3 - S x^2 + T x - 1 with S=(-1+s)/2, T=(-1-s)/2
S=sc(F(1,2),(-1,1)); T=sc(F(1,2),(-1,-1))
print("S =",show(S)," T =",show(T))
print("S+T =",show(add(S,T)),"  (expect -1)")
print("S*T =",show(mul(S,T)),"  (expect 2)")
print("S-T =",show(sub(S,T)),"  (expect s = i*sqrt7)")

# polynomials as lists of coefficients (Q(s) elements), low degree first
f=[(-1,F(0)), T, sc(-1,S), ONE]     # x^3 - S x^2 + T x - 1
g=[(-1,F(0)), S, sc(-1,T), ONE]     # x^3 - T x^2 + S x - 1
def polymul(p,q):
    r=[(F(0),F(0))]*(len(p)+len(q)-1)
    for i,a in enumerate(p):
        for j,b in enumerate(q):
            r[i+j]=add(r[i+j],mul(a,b))
    return r
prod=polymul(f,g)
print("product f*g =", [show(c) for c in prod])
phi7=[(F(1),F(0))]*7
print("equals Phi_7 ?", prod==phi7)
print("f coefficients:", [show(c) for c in f])
print("g coefficients:", [show(c) for c in g])
"}

