from fractions import Fraction

a = math.pi/3

def series(x, N=25):
    h = x - a
    s = 0.0
    for k in range(N):
        s += ((-1)**k / 2.0) * h**(2*k) / math.factorial(2*k)
        s += -((-1)**k * math.sqrt(3)/2.0) * h**(2*k+1) / math.factorial(2*k+1)
    return s

# also the single-sum form with cos(pi/3 + n*pi/2)
def series_single(x, N=40):
    h = x - a
    return sum(math.cos(a + n*math.pi/2)/math.factorial(n) * h**n for n in range(N))

for x in [0.0, 0.5, 1.0, 2.0, 3.0, 5.0, 10.0, -7.3]:
    s = series(x)
    s2 = series_single(x)
    t = math.cos(x)
    print(f"x={x:7.2f}  cos(x)={t: .15f}  split={s: .15f}  single={s2: .15f}  err_split={abs(s-t):.3e}  err_single={abs(s2-t):.3e}")

# check the first coefficients numerically against the listed rational/surd values
for n, c in enumerate([0.5, -math.sqrt(3)/2, -0.25, math.sqrt(3)/12, 1/48, -math.sqrt(3)/240, -1/1440]):
    fn = math.cos(a + n*math.pi/2)
    print(n, round(fn/math.factorial(n), 12), round(c, 12), abs(fn/math.factorial(n)-c) < 1e-12)
